33	+public class OrderService(AppDbContext db)
34	+{
35	+    public async Task<OrderCreateResult> CreateOrderAsync(OrderCreateDto request, CancellationToken cancellationToken = default)
36	+    {
37	+        if (request.Items.Count == 0)
38	+        {
39	+            return OrderCreateResult.Invalid("Der Warenkorb ist leer.");
40	+        }
41	+
42	+        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
43	+
44	+        var order = new Order
45	+        {
46	+            PublicId = Guid.NewGuid(),
47	+            Status = OrderStatus.Received,
48	+            DeliveryName = request.Delivery.Name,
49	+            DeliveryStreet = request.Delivery.Street,
50	+            DeliveryPostalCode = request.Delivery.PostalCode,
51	+            DeliveryCity = request.Delivery.City,
52	+            DeliveryCountry = request.Delivery.Country,
53	+            DeliveryEmail = request.Delivery.Email,
54	+            DeliveryPhone = request.Delivery.Phone,
55	+            CreatedAt = DateTime.UtcNow,
56	+        };
57	+
58	+        var responseItems = new List<OrderItemResponseDto>();
59	+
60	+        foreach (var line in request.Items)
61	+        {
62	+            if (line.Quantity < 1)
63	+            {
64	+                return OrderCreateResult.Invalid($"Ungültige Menge für Produkt '{line.ProductId}'.");
65	+            }
66	+
67	+            var offer = await db.Offers
68	+                .Where(o => o.ProductId == line.ProductId && o.SupplierId == line.SupplierId)
69	+                .Select(o => new { o.Price, ProductName = o.Product.Name, SupplierName = o.Supplier.Name })
70	+                .SingleOrDefaultAsync(cancellationToken);
71	+
72	+            if (offer is null)
73	+            {
74	+                return OrderCreateResult.Invalid(
75	+                    $"Angebot für Produkt '{line.ProductId}' bei Lieferant '{line.SupplierId}' ist nicht mehr verfügbar.");
76	+            }
77	+
78	+            order.Items.Add(new OrderItem
79	+            {
80	+                ProductId = line.ProductId,
81	+                SupplierId = line.SupplierId,
82	+                Quantity = line.Quantity,
83	+                UnitPriceAtOrder = offer.Price,
84	+            });
85	+
86	+            responseItems.Add(new OrderItemResponseDto
87	+            {
88	+                ProductId = line.ProductId,
89	+                ProductName = offer.ProductName,
90	+                SupplierId = line.SupplierId,
91	+                SupplierName = offer.SupplierName,
92	+                UnitPrice = offer.Price,
93	+                Quantity = line.Quantity,
94	+                LineTotal = offer.Price * line.Quantity,
95	+            });
96	+        }
97	+
98	+        db.Orders.Add(order);
99	+        await db.SaveChangesAsync(cancellationToken);
100	+        await transaction.CommitAsync(cancellationToken);
101	+
102	+        return OrderCreateResult.Ok(new OrderDto
103	+        {
104	+            PublicId = order.PublicId,
105	+            Status = order.Status.ToString(),
106	+            Delivery = request.Delivery,
107	+            Items = responseItems,
108	+            TotalAmount = responseItems.Sum(i => i.LineTotal),
109	+            CreatedAt = order.CreatedAt,
110	+        });
111	+    }
112	+}
