1011	+
1012	+type DeliveryFormState = Delivery;
1013	+
1014	+const EMPTY_DELIVERY: DeliveryFormState = {
1015	+  name: '', street: '', postalCode: '', city: '', country: '', email: '', phone: '',
1016	+};
