1029	+  protected readonly items = this.cartService.items;
1030	+  protected readonly totalAmount = this.cartService.totalAmount;
1031	+  protected readonly delivery = signal<DeliveryFormState>(EMPTY_DELIVERY);
1032	+  protected readonly submitting = signal(false);
